#include <sstream>
#include <string>
#include <vector>

struct DefExport
{
    std::string name;
    std::string internal;
    int ordinal{ -1 };
    bool noName{ false };
    bool data{ false };
};

std::vector<DefExport> readDef(const std::string& text)
{
    std::vector<DefExport> exports;
    std::istringstream lines{ text };
    std::string line;
    while (std::getline(lines, line))
    {
        // put spaces around = and @ so the words split cleanly
        std::string spaced;
        for (char c : line)
        {
            if (c == '=') spaced += " = ";
            else if (c == '@') spaced += " @";
            else spaced += c;
        }
        std::istringstream words{ spaced };
        std::vector<std::string> w;
        for (std::string word; words >> word;) w.push_back(word);
        if (w.empty() || w[0][0] == ';' || w[0] == "LIBRARY" || w[0] == "EXPORTS") continue;

        DefExport e;
        e.name = w[0];
        e.internal = w[0];
        std::size_t i{ 1 };
        if (i + 1 < w.size() && w[i] == "=") { e.internal = w[i + 1]; i += 2; }
        for (; i < w.size(); ++i)
        {
            if (w[i][0] == '@') e.ordinal = std::stoi(w[i].substr(1));
            else if (w[i] == "NONAME") e.noName = true;
            else if (w[i] == "DATA") e.data = true;
        }
        exports.push_back(e);
    }
    return exports;
}

unitTests:
TEST("the example") {
    const auto e = readDef("LIBRARY StoneMath
EXPORTS
    stackHeight       @1
    internalCounter   @3   DATA
    debugDump         @4   NONAME
    StackHeight = stackHeight
");
    CHECK_EQ(e.size(), std::size_t{ 4 });
    CHECK_EQ(e[0].name, std::string("stackHeight")); CHECK_EQ(e[0].internal, std::string("stackHeight")); CHECK_EQ(e[0].ordinal, 1); CHECK(!e[0].data); CHECK(!e[0].noName);
    CHECK_EQ(e[1].name, std::string("internalCounter")); CHECK_EQ(e[1].ordinal, 3); CHECK(e[1].data);
    CHECK_EQ(e[2].name, std::string("debugDump")); CHECK_EQ(e[2].ordinal, 4); CHECK(e[2].noName);
    CHECK_EQ(e[3].name, std::string("StackHeight")); CHECK_EQ(e[3].internal, std::string("stackHeight")); CHECK_EQ(e[3].ordinal, -1);
}
TEST("comments and blank lines") {
    const auto e = readDef("; my library

EXPORTS
  ; a comment
  first

  second
");
    CHECK_EQ(e.size(), std::size_t{ 2 }); CHECK_EQ(e[0].name, std::string("first")); CHECK_EQ(e[1].name, std::string("second"));
}
TEST("no spaces around = and @") {
    const auto e = readDef("EXPORTS
Pub=impl@7 NONAME DATA
");
    CHECK_EQ(e.size(), std::size_t{ 1 }); CHECK_EQ(e[0].name, std::string("Pub")); CHECK_EQ(e[0].internal, std::string("impl")); CHECK_EQ(e[0].ordinal, 7); CHECK(e[0].noName); CHECK(e[0].data);
}
TEST("words in either order") { const auto e = readDef("EXPORTS
 x @2 DATA NONAME
"); CHECK(e[0].data); CHECK(e[0].noName); CHECK_EQ(e[0].ordinal, 2); }
TEST("nothing") { CHECK(readDef("").empty()); CHECK(readDef("LIBRARY a
EXPORTS
").empty()); }

